// constat:template id=jest-check-report version=52 sha256=66565c726f1aa1915d8c0c16b686a3baac770befe4c1da8087a5e97681bda1c4
// Generated by DoneMark's onboarding pull request. Turns a jest --json report into the
// machine-readable per-check report CI publishes as the "constat-check-report" (and, on
// pull requests, "constat-check-report-base") workflow artifact. DoneMark's collector
// downloads that artifact and reads the named checks out of it — nothing an agent writes in its
// own report reaches this file.
//
// Usage: node .github/scripts/constat-jest-report.mjs <jestJsonFile> <outputFile> [--expected <headReport>]

import { existsSync, mkdirSync, readFileSync, writeFileSync } from 'node:fs';
import { dirname, relative, resolve } from 'node:path';

const [, , jestJsonFile, outputFile, ...rest] = process.argv;
const expectedFlag = rest.indexOf('--expected');
const expectedFile = expectedFlag === -1 ? null : rest[expectedFlag + 1];
if (!jestJsonFile || !outputFile || (expectedFlag !== -1 && !expectedFile)) {
  console.error('usage: constat-jest-report.mjs <jestJsonFile> <outputFile> [--expected <headReport>]');
  process.exit(2);
}

const STATUS = { passed: 'passed', failed: 'failed', pending: 'skipped', skipped: 'skipped', todo: 'skipped' };
const repoRoot = process.cwd();
// The picture a check took, if it took one: `.constat/pictures/<slug>.png`, the same slug rule as
// pictureSlug in @constat/shared, inlined because this file runs on a bare runner. The file's
// presence IS the message — nothing has to tell this script the name.
const slug = (name) => name.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '').slice(0, 120);
const picturesDir = resolve(repoRoot, '.constat', 'pictures');
const pictureFor = (name) => {
  const file = `${slug(name)}.png`;
  return existsSync(resolve(picturesDir, file)) ? file : null;
};

if (!existsSync(jestJsonFile)) {
  console.error(`${jestJsonFile} does not exist — refusing to publish an empty check report. Did jest run?`);
  process.exit(1);
}

const body = JSON.parse(readFileSync(jestJsonFile, 'utf8'));
const checks = [];
for (const suite of body.testResults ?? []) {
  const file = typeof suite.name === 'string' ? relative(repoRoot, resolve(suite.name)) : null;
  for (const assertion of suite.assertionResults ?? []) {
    const status = STATUS[assertion.status];
    if (typeof assertion.title !== 'string' || !status) continue;
    const ancestors = Array.isArray(assertion.ancestorTitles) ? assertion.ancestorTitles : [];
    const name = [...ancestors, assertion.title].join(' > ');
    const picture = expectedFile ? null : pictureFor(name);
    checks.push({ name, status, file, ...(picture ? { picture } : {}) });
  }
}

let published = checks;
if (expectedFile) {
  if (!existsSync(expectedFile)) {
    console.error(`expected head report ${expectedFile} does not exist — refusing to publish a before-code report with nothing to compare against.`);
    process.exit(1);
  }
  const expectedBody = JSON.parse(readFileSync(expectedFile, 'utf8'));
  const expectedChecks = Array.isArray(expectedBody) ? expectedBody : (expectedBody.checks ?? []);
  const expectedNames = [...new Set(expectedChecks.map((c) => c?.name).filter((n) => typeof n === 'string'))];
  if (expectedNames.length === 0) {
    console.error(`head report ${expectedFile} names no checks — nothing to compare against.`);
    process.exit(1);
  }
  const byName = new Map();
  for (const check of checks) {
    if (!byName.has(check.name)) byName.set(check.name, []);
    byName.get(check.name).push(check);
  }
  published = expectedNames.flatMap((name) => {
    const ran = byName.get(name);
    if (ran && ran.length > 0) return ran;
    return [{ name, status: 'could_not_run', file: null }];
  });
}

mkdirSync(dirname(outputFile), { recursive: true });
writeFileSync(
  outputFile,
  `${JSON.stringify({ schema: 'constat.check-report/v1', checks: published }, null, 2)}\n`,
);
console.log(
  `wrote ${published.length} check(s) to ${outputFile}${expectedFile ? ` (before-code mode, against ${expectedFile})` : ''}`,
);
